    ["pastor glen opened [church|shelter] at [Rosewood Baptist|First Baptist]. [tonight|by dark]"] = "格伦牧师开放了[教堂|避难所]：[罗斯伍德浸信会|第一浸信会]。[今晚|天黑前]",
    ["prescription ready at [Rosewood Pharmacy|Muldraugh Drug]. [mom's|dad's|grandma's]"] = "处方药在[罗斯伍德药房|马尔德劳药店]备好了。[妈妈的|爸爸的|奶奶的]",
    ["hide the [cash|keys|shotgun] in [attic vent|false bottom|dryer lint trap]"] = "把[现金|钥匙|猎枪]藏在[阁楼通风口|夹层底|烘干机滤网]里",
    ["if [power|water] goes: [candles|lanterns] in hall closet. [matches|light] top drawer"] = "如果[停电|断水]：[蜡烛|提灯]在走廊壁橱。[火柴|打火机]在最上面的抽屉",
    ["[ray|the tower guy] said [KM-09|the West Point site] down. [generator|battery] low"] = "[雷|信号塔那个人]说[KM-09|西点镇基站]挂了。[发电机|电池]电量低",
    ["lonnie stuck at [31W|the checkpoint] with [produce|a full load]. [CB|radio] ch 19"] = "朗尼困在[31W|检查站]，带着[农产品|满载货物]。[CB|无线电]19频道",
    ["[dee|darlene] at dispatch: [curfew|10-4] at dark. stay in"] = "[迪伊|达琳]在调度台：天黑[宵禁|10-4]。待在屋里",
    ["deputy [lusk|wade] went to [Main St|the courthouse] call. [hasnt|hasn't] come back"] = "副警长[拉斯克|韦德]去了[主街|法院]的报警。[没|还没]回来",
    ["[dr sato|ellen] texted: [dont come|stay away] from ER. full"] = "[佐藤医生|艾伦]发短信：急诊室[别来|离远点]。满了",
    ["[trish|nurse] pulled [double|another] shift. [coffee|sleep] in break room"] = "[特丽什|护士]又上了[双倍|另一个]班。[咖啡|睡觉]在休息室",
    ["[earl|grandpa] says [CB|radio] quiet. weather at 6 on ch 9"] = "[厄尔|爷爷]说[CB|无线电]没声了。6点天气预报，9频道",
    ["[hank|gun store] sold out [Friday|by noon]. [people at door|line around block]"] = "[汉克|枪店][周五|中午前]就卖光了。[门口都是人|队伍排了一圈]",
    ["[marla|the lake lady] says [cabins|keys under mat] at West Point. empty"] = "[玛拉|湖边那位女士]说西点镇的[小木屋|垫子下的钥匙]。空的",
    ["[june|courthouse] staying for [records|the list]. [doors locked|nobody in]"] = "[琼|法院]留下来处理[记录|名单]。[门锁了|里面没人]",
    ["[lyle|prison guard] says [lockdown|quiet] at Rosewood. nobody leaving"] = "[莱尔|监狱看守]说罗斯伍德[封锁|平静]。没人出得去",
    ["[carl|foreman] keeping [night shift|the guys] at steelworks. gates locked"] = "[卡尔|工头]把[夜班|工人们]留在钢厂。大门锁了",
    ["[grace|country club] party [ended early|cut short]. fireworks at dark"] = "[格蕾丝|乡村俱乐部]的聚会[提前结束了|被迫中断]。天黑放烟花",
    ["[jimmy|twiggys] says [back door|knock 3]. shotgun inside. dont knock"] = "[吉米|twiggys]说[后门|敲3下]。里面有猎枪。别敲门",
    ["[becky|mall clerk] sleeping in [stockroom|Crossroads]. [mall closed|mom alone]"] = "[贝基|商场店员]睡在[库房|十字路口购物中心]。[商场关了|妈妈一个人]",
    ["[wendell|speedway] planned [last race|Saturday]. [nobody|nobody came|empty stands]"] = "[温德尔|赛车场]原定[最后一场比赛|周六]。[没人|没人来|看台空了]",
    ["[missy|motel clerk] rented [rooms|302 304 307]. [never checked out|keys still out]"] = "[米西|旅馆前台]出租了[房间|302 304 307]。[一直没退房|钥匙还在外面]",
    ["[rev lois|march ridge] making [list|pantry list]. missing growing. food"] = "[洛伊丝牧师|三月岭]在做[名单|储藏室清单]。失踪的越来越多。食物",
    ["[tony|pizza] cant get [through|to hospital]. roadblock at river"] = "[托尼|披萨店]没法[通过|去医院]。河边有路障",
    ["[shirley|grandma] texts [every day|every morning]. [neighbor|mrs davis] answered today"] = "[雪莉|奶奶][每天|每早]发短信。[邻居|戴维斯太太]今天回了",
    ["[doug|mailman] marked [houses|route] with no answer. 7 so far"] = "[道格|邮递员]把没人应门的[房子|路线]标出来了。目前7户",
    ["Day [3|4|5]. [no TV|no phone|no power]. waiting for [{partner}|{mom}|{dad}]"] = "第[3|4|5]天。[没电视|没电话|没电]。在等[{partner}|{mom}|{dad}]",
    ["if i dont [text|call] by [6|dark|noon] [dont come|stay put|lock door]"] = "如果我[6点|天黑|中午]前不[发短信|打电话]，[别来|待在原地|锁好门]",
    ["[{partner}|{friend}] has the [keys|gun|truck]. meet at {jobPlace}"] = "[{partner}|{friend}]拿着[钥匙|枪|卡车]。在{jobPlace}碰头",
    ["heard [shots|screams|trucks] on [Main|31W|river road] at 2am. dog didnt wake"] = "凌晨2点在[主街|31W|河边路]听到[枪声|尖叫声|卡车声]。狗没醒",
    ["[{mom}|{dad}] said [come home|stay there|pray]. cant leave"] = "[{mom}|{dad}]说[回家|待在那儿|祈祷]。走不了",
    ["It's Mom. Your father's phone goes straight to voicemail. And you're not answering. [Honey|{first}], please. Just pick up. [I'm|We're] scared."] = "是妈妈。你爸的手机直接转语音信箱。你也不接。[宝贝|{first}]，求你了。接电话吧。[我|我们]好害怕。",
    ["[{first}|Hey]. The kids are asking for you. [I|We] told you're working. Call me. Please."] = "[{first}|嘿]。孩子们在找你。[我|我们]说你在上班。给我回电话。求你了。",
    ["It's me. Your father checked the generator [this morning|again at noon] and it's holding. Call me back when you can"] = "是我。你爸[今早|中午又]检查了发电机，还撑得住。有空给我回电话",
    ["Honey, I tried the house phone again. Nothing. Your [sister|brother] went to the IGA for water. Call me back, hon"] = "宝贝，我又试了家里的电话。没声音。你[姐姐|哥哥]去IGA拿水了。给我回电话，亲爱的",
    ["It's me. Grandma's fan quit [around three|after lunch]. We gave her the one from the hall closet. Call me when you get this"] = "是我。奶奶的风扇[三点左右|午饭后]坏了。我们把走廊壁橱里那个给她了。你收到后给我打电话",
    ["It's your father. The truck's still making that knock. I'll look at it Sunday. Call me back"] = "我是你爸。卡车还在发那种敲击声。周日我看看。给我回电话",
    ["Your mother's worried. She won't say it but I can tell. Call home. Let us know you're all right"] = "你妈很担心。她嘴上不说，但我看得出来。往家里打个电话。让我们知道你没事",
    ["It's Dad. The cooler's still in the bed of the truck from the Fourth. Bring it back when you can"] = "我是爸爸。自从七月四日那次，保温箱还在卡车车斗里。有空把它带回来",
    ["its me. moms making her [famous|awful] potato salad tomorrow. she said ask if youre coming. call me back"] = "是我。妈明天要做她[出名的|难吃的]土豆沙拉。她让我问你来不来。给我回电话",
    ["hey its me. found dads old CB in the garage. mostly static but i heard voices by the river. call back"] = "嘿是我。在车库里找到爸的旧CB电台。大多是杂音，但我听到河边有人说话。回电话",
    ["its me. the lights went out at moms [around eight|just now]. generator kicked on. call me back please"] = "是我。妈家的灯[八点左右|刚才]灭了。发电机自己启动了。请回我电话",
    ["It's me. I kept the porch light on [like you asked|anyway]. The kids are asleep. Please call me back"] = "是我。我[像你说的那样|还是]把门廊灯开着。孩子们睡了。请给我回电话",
    ["It's me. The baby finally went down after the sirens stopped. I'm just sitting here with the phone. Call me"] = "是我。警笛停了以后宝宝终于睡着了。我就拿着电话坐在这儿。给我打电话",
    ["It's me. Your keys are in the bowl by the door. I didn't move them. Call me back. Please"] = "是我。你的钥匙在门边的碗里。我没动。给我回电话。求你了",
    ["Hey. It's me. The car's still in the drive with [half a tank|the gas light on]. Call me when you get this"] = "嘿。是我。车还停在车道上，[油箱还剩半箱|油灯亮着]。收到后给我打电话",
    ["its me. the kroger on dixie got a truck in. water, cans, batteries. line's long. call me back"] = "是我。迪克西路的kroger来了一车货。水，罐头，电池。队很长。回我电话",
    ["its me. heard popping by the [lumberyard|school] around midnight. probably nothing. call me back"] = "是我。午夜前后在[木材厂|学校]那边听到啪啪声。多半没事。回我电话",
    ["This is {work} at {jobPlace}. Your shift [tomorrow|Saturday] is covered. Call us back when you get this"] = "这里是{jobPlace}的{work}。你[明天|周六]的班有人顶了。收到后给我们回电话",
    ["It's {work}. We're running short on the night crew. Call in when you can. We're holding your spot"] = "是{work}。夜班人手不够。有空就打进来。我们给你留着位置",
    ["This is {work}. The chief wants a headcount. Call in when you get this"] = "这里是{work}。队长要统计人数。收到后打进来",
    ["It's your mother. I put fresh sheets on your bed. The blue ones you like. Call me back, honey"] = "我是你妈。给你的床换了新床单。你喜欢的蓝色那套。给我回电话，宝贝",
    ["hey its me. found your old baseball glove in the hall closet. thought youd want it. call me"] = "嘿是我。在走廊壁橱里找到你的旧棒球手套。想着你会要。给我打电话",
    ["It's me. I filled the tub and the big pots like you said. Just in case. Call me"] = "是我。我按你说的把浴缸和大锅都装满了水。以防万一。给我打电话",
    ["It's me. The dog won't stop whining at the back door. It's been hours. Call me please"] = "是我。狗在后门一直呜呜叫。好几个小时了。请给我打电话",
    ["[Coffee|Coffee's] ready in the break room. [Fresh pot|Burnt again]"] = "休息室里[咖啡|新煮的咖啡]好了。[刚煮的|又糊了]",
    ["Anyone seen my [clipboard|radio charger]? Left it by the [dispatch board|coffee maker]"] = "有人看见我的[写字板|对讲机充电器]了吗？落在[调度板|咖啡机]那儿了",
    ["[Trish|Dee] swapped with me for [tonight|tomorrow night]. [Thanks|Owe you one]"] = "[特里什|迪伊]和我换班了，换到[今晚|明晚]。[谢啦|欠你一个人情]",
    ["Road crew hit a water main on [31W|Main St]. [Expect delays|Detour by the plant]"] = "道路施工队在[31W|Main St]挖破了一根水管。[预计会堵车|从水厂那边绕行]",
    ["[Unit 4|Medic 2] back in service. [Cleaned up|Restocked] and ready"] = "[4号车|急救2号]恢复服役。[已清理干净|已补充物资]，随时待命",
    ["Shift change in [10|15]. [Relief's|The next crew's] pulling in now"] = "[10|15]分钟后换班。[接班的人|下一班的人]正在进场",
    ["[Lunch|Dinner] run to [Spiffo's|the diner]. [Want anything|Grab me a burger]?"] = "[午饭|晚饭]时间去[Spiffo's|餐馆]跑一趟。[要带点什么吗|帮我带个汉堡]？",
    ["AC's acting up in [dispatch|the squad room] again. [Maintenance|Facilities] says [Tuesday|next week]"] = "[调度室|小队办公室]的空调又出毛病了。[维修部|后勤]说[周二|下周]来修",
    ["[Wade|Deputy Lusk] called out sick. [Flu|Something going around]. [Cover|Need someone] for his sector"] = "[韦德|拉斯克副警长]请病假了。[流感|最近到处在传的病]。[得有人替|需要人顶]他那个片区",
    ["New guy starts [Monday|Wednesday]. [Show him the ropes|Don't let him break anything]"] = "新来的[周一|周三]上班。[带带他|别让他把东西搞坏了]",
    ["[Carl|The foreman] wants the [night shift|weekend crew] on the furnace line. Overtime"] = "[卡尔|工头]想让[夜班|周末班组]去熔炉线。有加班费",
    ["Generator test at [0800|noon]. [Expect noise|Power flicker] for a minute"] = "发电机测试在[8点|中午]。[会有噪音|会闪一下电]，就一分钟",
    ["[Tammy|Missy] at the [motel|Spiffo's] says business is slow. Lucky her"] = "[汽车旅馆|Spiffo's]的[塔米|米西]说生意冷清。她真走运",
    ["County [fair|softball tournament] this weekend. [Sign up|Who's playing] at the [station|break room] board"] = "这周末有县里的[集市|垒球锦标赛]。去[警局|休息室]的告示板那儿[报名|看看谁来打]",
    ["[Ray|The tower tech] was out at [KM-09|KM-12] all night. Site's up. Good work"] = "[雷|信号塔技术员]在[KM-09|KM-12]待了一整夜。站点恢复了。干得好",
    ["[Dr. Sato|Ellen] sent a memo: [hydration breaks|watch for heat exhaustion] every hour. [Serious|Not optional]"] = "[佐藤医生|埃伦]发了备忘录：每小时[补水休息|留意中暑]。[是认真的|没得商量]",
    ["Pharmacy on [Dixie|Main] ran out of [IV bags|saline]. [Central supply|The hospital] sending a crate"] = "[Dixie|Main]上的药店[静脉输液袋|生理盐水]断货了。[中央供应处|医院]正送一箱过来",
    ["[Lou|The captain] wants [incident reports|run sheets] done before shift end. No exceptions"] = "[卢|队长]要求[事故报告|出勤记录]在下班前交。没有例外",
    ["Kids' [soccer|baseball] game at the [school|field] Saturday. [Concession stand|Scoreboard] needs volunteers"] = "孩子们的[足球|棒球]赛周六在[学校|球场]。[小卖部|记分牌]那儿缺志愿者",
    ["[Jimmy|The bartender] says [Twiggy's|the bar] closed Monday for repairs. Weird"] = "[吉米|酒保]说[Twiggy's|酒吧]周一关门修理。怪了",
    ["Mail's running [late|early] today. [Doug|The carrier] said bridge work on 31W"] = "今天邮件[晚|早]了。[道格|邮递员]说31W在修桥",
    ["[All circuits busy|Lines jammed] on the [landlines|radio]. [Cell's|Knox Mobile] still working tho"] = "[线路全忙|线路堵死了]，[座机|电台]打不通。[手机|Knox Mobile]倒还能用",
    ["Heard [Louisville|the city] ER's [overflowing|on divert]. Dr. Sato hasn't gone home in two days"] = "听说[路易斯维尔|市里]的急诊室[人满为患|在分流]。佐藤医生两天没回家了",
    ["[Pastor Glen|The church] opened the [basement|fellowship hall] for anyone. Cots needed"] = "[格伦牧师|教堂]把[地下室|团契大厅]开放给所有人。需要行军床",
    ["[Coach Burris|Dale] cancelled [practice|weights] tomorrow. [First time|Never] seen him do that"] = "[伯里斯教练|戴尔]取消了明天的[训练|力量训练]。[头一回|从没]见他这样",
    ["National Guard at the [31W|county line] checkpoint. [Turning cars|Checking IDs]. [Nobody|Few] getting through"] = "国民警卫队在[31W|县界]检查站。[劝返车辆|查证件]。[一个都|几乎没人]过得去",
    ["[Lonnie|The trucker] stuck at the [roadblock|fence] with a full trailer. Since midnight"] = "[朗尼|那个卡车司机]被困在[路障|围栏]那儿，拉着一整车货。从午夜起就这样",
    ["[Trish|Dee] says [the hospital|ER] locked the ambulance bay. Walk-ins only"] = "[特里什|迪伊]说[医院|急诊室]把救护车通道锁了。只收步行来的",
    ["Dispatch getting [calls|reports] of [people biting|fights] on Main. Send two units"] = "调度台接到[来电|报告]，Main上有[人咬人|打架]。派两个小队过去",
    ["[Wade|Deputy Lusk] went to a [disturbance|call] on Main St 20 mins ago. No answer"] = "[韦德|拉斯克副警长]20分钟前去Main St处理[骚乱|警情]。联系不上",
    ["[Ray|Pruitt] headed to [KM-07|the Riverside site] on foot. Tower's down. Be careful"] = "[雷|普鲁伊特]步行去[KM-07|河畔镇站点]了。信号塔瘫了。小心点",
    ["Landlines [dead|gone] in [Rosewood|Muldraugh|West Point]. Cell only thing working. Keep phones charged"] = "座机[断了|没了]，就在[罗斯伍德|马尔德劳|西点镇]。只有手机还能用。保持手机有电",
    ["[Lyle|Fentress] at the [prison|Rosewood] says lockdown. No visits. Quiet"] = "[莱尔|芬特雷斯]在[监狱|罗斯伍德]说实行封锁。禁止探视。很安静",
    ["[Missy|The motel clerk] rented [every room|the last six] to families with cash. Nobody checked out"] = "[米西|汽车旅馆前台]把[所有房间|最后六间]租给了付现金的家庭。没人退房",
    ["[Gus|Oberholtzer] at the [Brott farm|Irvington] says cattle been bellowing all night. Never heard that before"] = "[格斯|奥伯霍尔泽]在[布罗特农场|欧文顿]说牛叫了一整夜。以前从没听过那样的叫声",
    ["[Tony|DeLuca] tried [three|four] runs to the hospital. Blocked at the checkpoint every time"] = "[托尼|德卢卡]往医院跑了[三|四]趟。每次都被检查站拦下",
    ["[Grace|Pettit] at the [Country Club|West Maple] said the Fourth party ended early. People left fast"] = "[格蕾丝|佩蒂特]在[乡村俱乐部|West Maple]说七月四日的派对提前散了。人们走得很急",
    ["[Earl|Pickett] on CB says [sky's|air's] wrong over Irvington. No birds"] = "[厄尔|皮克特]在CB电台说欧文顿上空[天空|空气]不对劲。一只鸟都没有",
    ["[Rev. Abney|Lois] at [March Ridge|the Methodist church] started a list of missing. Names growing"] = "[阿布尼牧师|洛伊丝]在[三月岭|卫理公会教堂]列了一份失踪者名单。名字越来越多",
    ["[Shirley|Grandma Mattingly] didn't answer her [phone|door] today. Neighbor said she's fine. Checked twice"] = "[雪莉|马丁利奶奶]今天没[接电话|开门]。邻居说她没事。查看了两次",
    ["[Sgt. Bell|Marcus] texted [his wife|home]: can't say. At the checkpoint. Last message"] = "[贝尔中士|马库斯]给[他妻子|家里]发短信：不能说。在检查站。最后一条消息",
    ["[Danny|Coyle] texted his [mom|mother]: pray for us. Private from Ohio. Stopped since yesterday"] = "[丹尼|科伊尔]给他[妈妈|母亲]发短信：为我们祈祷。俄亥俄来的列兵。从昨天起就没再发了",
    ["If [anyone|you] gets [through|a signal] on the radio, relay dispatch we're holding. Don't leave {jobPlace}"] = "如果[有人|你]在电台上[联系上了|收到信号]，转告调度我们还在坚守。别离开{jobPlace}",
    ["[Last|Final] check: [water|coffee|ammo|batteries] in the locker. Enough. Ration it"] = "[最后|最终]检查：储物柜里的[水|咖啡|弹药|电池]。够用。要省着用",
    ["Dispatch log: Lusk 10-7 Main St 0200. No 10-8. Radio silent. Wade? You copy? {town}"] = "调度日志：拉斯克10-7，Main St，0200。没有10-8。电台无声。韦德？收到请回答？{town}",
}
